mapper.update:
UPDATE dividends
   SET net_amount_usd = #{netAmountUsd},
       fx_rate        = #{fxRate},
       net_amount_krw = #{netAmountKrw},
       pay_date       = #{payDate}
 WHERE id = #{id}
   AND user_id = #{userId}
   AND deleted_at IS NULL

UPDATE dividends
   SET deleted_at = NOW(3)
 WHERE id = #{id}
   AND user_id = #{userId}
   AND deleted_at IS NULL

mapper.select:
SELECT SUM(net_amount_krw)
  FROM dividends
 WHERE user_id = #{userId}
   AND status = 'CONFIRMED'
   AND pay_date BETWEEN #{from} AND #{to}
   AND deleted_at IS NULL
